# -*- coding: utf-8 -*-

'''A group of TextSpan and ImageSpan objects.
'''

from ..common.Collection import ElementCollection
from .TextSpan import TextSpan
from ..image.ImageSpan import ImageSpan

class Spans(ElementCollection):
    '''Collection of TextSpan and ImageSpan instances.'''

    def restore(self, raws:list):
        '''Recreate TextSpan or ImageSpan from source dict list.'''
        spans = []
        for raw_span in raws:
            if 'image' in raw_span:
                spans.append(ImageSpan(raw_span))
                continue

            span = TextSpan(raw_span)
            if not span.text:
                continue                  # 连字符都没有(控制字符被过滤后的残留)

            # 【本仓库改动】纯空格的 span **不能丢,也不能留成独立实例**。
            #
            # 不能丢:PDF(LaTeX/dvipdfmx 出的尤其明显)经常把单词之间的空格单独切成
            # 一个 span —— "Benchmarks and comparison methods" 实际是
            # ['Benchmarks',' ','and',' ','comparison',' ','methods'],丢掉空格整篇
            # 英文就黏成 "Benchmarksandcomparisonmethods"。
            #
            # 不能留成独立实例:pdf2docx 的布局推断(flow layout / 表格 / 行分组)对
            # span 数是超线性的,多出来的空格 span 会让它慢到不可用 —— 实测同一页
            # 从 45s 涨到 289s。所以把空格**并进前一个文本 span**,字数不变、实例不增。
            if not span.text.strip():
                for 前 in reversed(spans):
                    if isinstance(前, TextSpan) and 前.chars:
                        for ch in span.chars:
                            前.add(ch)    # 同时把 bbox 撑到空格所在位置
                        break
                continue                  # 行首没有前一个文本 span 时就丢弃(等价 lstrip)

            spans.append(span)

        # 去掉行首/行尾的纯空白 span(段首缩进由 docx 样式管,不需要这些空格);
        # 行**中间**的空格 span 必须留着,否则相邻单词会黏在一起。
        while spans and isinstance(spans[0], TextSpan) and not spans[0].text.strip():
            spans.pop(0)
        while spans and isinstance(spans[-1], TextSpan) and not spans[-1].text.strip():
            spans.pop()

        for span in spans: self.append(span)
        return self

    @property
    def text_spans(self):
        '''Get TextSpan instances.'''
        spans = list(filter(
            lambda span: isinstance(span, TextSpan), self._instances
        ))
        return Spans(spans)

    @property
    def image_spans(self):
        '''Get ImageSpan instances.'''
        spans = list(filter(
            lambda span: isinstance(span, ImageSpan), self._instances
        ))
        return Spans(spans)


    def strip(self):
        '''Remove redundant blanks at the begin/end span.'''
        stripped = False
        if not self._instances: return stripped
        
        # left strip the first span
        left_span = self._instances[0]
        if isinstance(left_span, TextSpan): stripped = stripped or left_span.lstrip() 

        # right strip the last span
        right_span = self._instances[-1]
        if isinstance(right_span, TextSpan): stripped = stripped or right_span.rstrip()

        # update bbox
        if stripped: self._parent.update_bbox(self.bbox)

        return stripped